const rawInput = $input.first()?.json || {};
let rawAgent4Json = rawInput.agent4_json ?? rawInput['Agent 4 JSON 结果'] ?? rawInput.data ?? '';

// 去掉 Markdown 代码块外壳，方便用户直接粘贴报告里的 JSON。
function stripMarkdownFence(value) {
  const text = typeof value === 'string' ? value.trim() : value;
  if (typeof text !== 'string') return text;
  return text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
}

function looksLikeVisualPlan(item) {
  return !!item && typeof item === 'object' && (
    item.visual_style !== undefined || item.scenes !== undefined || item.ready_for_agent5 !== undefined || item.video_title !== undefined
  );
}

function unwrapAgent4Payload(value) {
  if (Array.isArray(value)) {
    const wrapper = value.find((item) => item && typeof item === 'object' && (Array.isArray(item.visual_plans) || Array.isArray(item.visual_projects)));
    if (wrapper) return wrapper;
    return { visual_plans: value.filter(looksLikeVisualPlan), status: value.length ? 'success' : 'insufficient_data', handoff: {} };
  }
  if (value && typeof value === 'object') return value;
  return {};
}

// 自动寻找 Agent 4 常见视觉方案数组，优先读取 visual_plans[]，兼容 visual_projects[] 和旧字段。
function findVisualPlans(payload) {
  if (!payload || typeof payload !== 'object') return [];
  const possibleKeys = ['visual_plans', 'visual_projects', 'plans', 'results', 'records', 'approved_visual_plans'];
  for (const key of possibleKeys) {
    if (Array.isArray(payload[key])) return payload[key];
  }
  return looksLikeVisualPlan(payload) ? [payload] : [];
}

function text(value) { return String(value ?? '').trim(); }
function normalizePlan(plan, index) {
  const scenes = Array.isArray(plan.scenes) ? plan.scenes : (Array.isArray(plan.scene_list) ? plan.scene_list : []);
  return {
    ...plan,
    script_id: text(plan.script_id || plan.id || `agent4_visual_plan_${index + 1}`),
    video_title: text(plan.video_title || plan.title || plan.topic || `Untitled Visual Plan ${index + 1}`),
    scenes,
    source_index: index + 1,
  };
}

try {
  let parsed = rawAgent4Json;
  if (typeof parsed === 'string') parsed = JSON.parse(stripMarkdownFence(parsed));
  const payload = unwrapAgent4Payload(parsed);
  const visual_plans = findVisualPlans(payload)
    .map((plan, index) => normalizePlan(plan, index))
    .filter((plan) => plan.video_title);
  return [{
    json: {
      status: 'parsed',
      parse_error: '',
      source_agent: 'agent_4',
      source_status: payload.status || '',
      source_handoff: payload.handoff || {},
      visual_plans,
      total_visual_plans: visual_plans.length,
    }
  }];
} catch (error) {
  return [{ json: { status: 'error', parse_error: `Agent 4 JSON 解析失败：${error.message}`, source_agent: 'agent_4', visual_plans: [], total_visual_plans: 0 } }];
}

const data = $input.first()?.json || {};
if (data.status === 'error') return [{ json: { ...data, voiceover_input_plans: [], selected_count: 0 } }];
function truthy(value) { return value === true || value === 1 || value === '1' || value === 'true' || value === 'True' || value === 'Yes' || value === 'yes'; }
const selected = (Array.isArray(data.visual_plans) ? data.visual_plans : [])
  .filter((plan) => truthy(plan.ready_for_agent5))
  .slice(0, 5);
return [{ json: { ...data, status: selected.length > 0 ? 'ready_for_voiceover' : 'insufficient_data', voiceover_input_plans: selected, selected_count: selected.length, selection_note: selected.length > 0 ? '已选择 ready_for_agent5 = true 的视觉方案。' : '没有 ready_for_agent5 = true 的视觉方案，Agent 5 不会生成配音或字幕。' } }];

const data = $input.first()?.json || {};
if (data.status === 'error' || data.status === 'insufficient_data') return [{ json: { ...data, draft_voiceover_packages: [] } }];
function text(value) { return String(value ?? '').trim(); }
function parseSeconds(value) { const m = text(value).match(/\d+(?:\.\d+)?/); return m ? Number(m[0]) : 0; }
function fmtSrtTime(seconds) {
  const totalMs = Math.max(0, Math.round(seconds * 1000));
  const h = String(Math.floor(totalMs / 3600000)).padStart(2, '0');
  const m = String(Math.floor((totalMs % 3600000) / 60000)).padStart(2, '0');
  const s = String(Math.floor((totalMs % 60000) / 1000)).padStart(2, '0');
  const ms = String(totalMs % 1000).padStart(3, '0');
  return `${h}:${m}:${s},${ms}`;
}
function cleanNarration(value, fallback) {
  const safe = text(value || fallback).replace(/\s+/g, ' ');
  return safe || 'Show this wellness moment clearly and calmly.';
}
function subtitleLine(value) {
  const clean = cleanNarration(value, '').replace(/[\n\r]+/g, ' ');
  return clean.length > 72 ? `${clean.slice(0, 69)}...` : clean;
}
function buildPackage(plan, index) {
  const scenes = plan.scenes.length ? plan.scenes : [{ scene_number: 1, start_time: '0s', end_time: '5s', duration_seconds: 5, narration_text: plan.video_title }];
  const segments = scenes.map((scene, sceneIndex) => {
    const start = parseSeconds(scene.start_time) || scenes.slice(0, sceneIndex).reduce((sum, item) => sum + Number(item.duration_seconds || 4), 0);
    const duration = Number(scene.duration_seconds || Math.max(3, parseSeconds(scene.end_time) - start) || 4);
    const end = start + duration;
    const narration = cleanNarration(scene.narration_text, plan.video_title);
    return {
      segment_number: sceneIndex + 1,
      scene_number: scene.scene_number || sceneIndex + 1,
      start_time_seconds: start,
      end_time_seconds: end,
      duration_seconds: duration,
      voiceover_text: narration,
      subtitle_text: subtitleLine(narration),
      pacing: duration <= 3 ? 'fast hook pace' : (duration >= 5 ? 'calm explanatory pace' : 'natural short-form pace'),
      delivery_notes: sceneIndex === 0 ? 'Open with clear energy in the first three seconds.' : 'Keep voice warm, clear, and educational.',
    };
  });
  const fullVoiceover = segments.map((s) => s.voiceover_text).join(' ');
  const srt = segments.map((s) => `${s.segment_number}\n${fmtSrtTime(s.start_time_seconds)} --> ${fmtSrtTime(s.end_time_seconds)}\n${s.subtitle_text}`).join('\n\n');
  return {
    package_id: `agent5_voiceover_${index + 1}`,
    source_script_id: plan.script_id,
    video_title: plan.video_title,
    language: 'en-US',
    voice_style: 'warm, calm, trustworthy wellness narrator',
    estimated_duration_seconds: segments.reduce((sum, s) => sum + Number(s.duration_seconds || 0), 0),
    full_voiceover_script: fullVoiceover,
    voiceover_script: fullVoiceover,
    voiceover_segments: segments,
    narration_segments: segments,
    subtitles: segments.map((s) => ({ index: s.segment_number, start: s.start_time_seconds, end: s.end_time_seconds, text: s.subtitle_text })),
    subtitle_segments: segments.map((s) => ({ index: s.segment_number, start: s.start_time_seconds, end: s.end_time_seconds, text: s.subtitle_text })),
    srt,
    voiceover_pacing: 'Start with a slightly brighter hook, then slow into calm educational pacing, and end with a gentle CTA.',
    pacing_notes: 'Start with a slightly brighter hook, then slow into calm educational pacing, and end with a gentle CTA.',
    tts_prompt: `Read in natural American English, warm and calm wellness tone, clear articulation, short-form social video pacing, no medical authority voice, no exaggerated claims. Title: ${plan.video_title}`,
  };
}
const draftVoiceoverPackages = (data.voiceover_input_plans || []).map(buildPackage);
return [{ json: { ...data, status: 'voiceover_drafted', draft_voiceover_packages: draftVoiceoverPackages } }];

const data = $input.first()?.json || {};
if (data.status === 'error' || data.status === 'insufficient_data') return [{ json: { ...data, qa_voiceover_packages: [] } }];
const riskyTerms = ['guaranteed result', 'cure', 'treat', 'treatment', 'prevent disease', 'replace medication', 'stop medication', 'FDA approved', 'clinically proven', '治愈', '治疗', '替代药物', '停止服药'];
const negativeContextWords = ['do not', "don't", 'avoid', 'never', 'no', 'not', 'without', 'instead of', 'do not present', 'do not claim', 'must not', 'should not', 'cannot', "can't", '禁止', '避免', '不要', '不得', '不能', '不应'];
function text(value) { return String(value ?? '').trim(); }
function escapeRegExp(value) { return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function phraseRegex(term) {
  const escaped = escapeRegExp(term).replace(/\s+/g, '\\s+');
  return /^[a-z0-9 ]+$/i.test(term) ? new RegExp(`\\b${escaped}\\b`, 'i') : new RegExp(escaped, 'i');
}
function splitSentences(value) {
  return text(value).split(/(?<=[.!?。！？])\s+|[;；\n]+/).map((item) => item.trim()).filter(Boolean);
}
function isNegativeContext(sentence, term) {
  const lower = sentence.toLowerCase();
  const termLower = term.toLowerCase();
  const index = lower.indexOf(termLower);
  const prefix = index >= 0 ? lower.slice(0, index) : lower;
  return negativeContextWords.some((word) => prefix.includes(word) || lower.startsWith(`${word} `));
}
function findRisk(value) {
  const matches = [];
  for (const sentence of splitSentences(value)) {
    for (const term of riskyTerms) {
      if (phraseRegex(term).test(sentence) && !isNegativeContext(sentence, term)) matches.push(term);
    }
  }
  return Array.from(new Set(matches));
}
function fmtSrtTime(seconds) {
  const totalMs = Math.max(0, Math.round(seconds * 1000));
  const h = String(Math.floor(totalMs / 3600000)).padStart(2, '0');
  const m = String(Math.floor((totalMs % 3600000) / 60000)).padStart(2, '0');
  const s = String(Math.floor((totalMs % 60000) / 1000)).padStart(2, '0');
  const ms = String(totalMs % 1000).padStart(3, '0');
  return `${h}:${m}:${s},${ms}`;
}
function qaPackage(pkg) {
  const issues = [];
  const corrections = [];
  const fixed = { ...pkg };
  if (!Array.isArray(fixed.voiceover_segments) || fixed.voiceover_segments.length === 0) {
    issues.push('缺少分句配音 segments。');
    fixed.voiceover_segments = [{ segment_number: 1, start_time_seconds: 0, end_time_seconds: 5, duration_seconds: 5, voiceover_text: fixed.video_title || 'General wellness video.', subtitle_text: fixed.video_title || 'General wellness video.', pacing: 'natural short-form pace', delivery_notes: 'Use a calm voice.' }];
    corrections.push('已补充分句配音占位。');
  }
  fixed.voiceover_segments = fixed.voiceover_segments.map((segment, index) => {
    const repaired = { ...segment };
    if (!repaired.segment_number || repaired.segment_number !== index + 1) { repaired.segment_number = index + 1; corrections.push(`修复第 ${index + 1} 条分句编号。`); }
    if (!text(repaired.voiceover_text)) { repaired.voiceover_text = fixed.video_title || 'General wellness video.'; corrections.push(`补充第 ${index + 1} 条配音文本。`); }
    if (!text(repaired.subtitle_text)) { repaired.subtitle_text = text(repaired.voiceover_text).slice(0, 72); corrections.push(`补充第 ${index + 1} 条字幕。`); }
    if (text(repaired.subtitle_text).length > 84) { repaired.subtitle_text = text(repaired.subtitle_text).slice(0, 81) + '...'; corrections.push(`缩短第 ${index + 1} 条字幕。`); }
    if (Number(repaired.end_time_seconds) <= Number(repaired.start_time_seconds)) { repaired.end_time_seconds = Number(repaired.start_time_seconds || index * 4) + Number(repaired.duration_seconds || 4); corrections.push(`修复第 ${index + 1} 条字幕时间。`); }
    return repaired;
  });
  fixed.full_voiceover_script = fixed.voiceover_segments.map((s) => s.voiceover_text).join(' ');
  fixed.subtitles = fixed.voiceover_segments.map((s) => ({ index: s.segment_number, start: s.start_time_seconds, end: s.end_time_seconds, text: s.subtitle_text }));
  fixed.srt = fixed.voiceover_segments.map((s) => `${s.segment_number}\n${fmtSrtTime(s.start_time_seconds)} --> ${fmtSrtTime(s.end_time_seconds)}\n${s.subtitle_text}`).join('\n\n');
  if (!text(fixed.tts_prompt)) { fixed.tts_prompt = `Read in natural American English, warm calm wellness tone. Title: ${fixed.video_title}`; corrections.push('补充 TTS Prompt。'); }
  const risk = findRisk(`${fixed.full_voiceover_script} ${fixed.srt} ${fixed.tts_prompt}`);
  if (risk.length > 0) issues.push(`配音或字幕中出现高风险医疗表达：${Array.from(new Set(risk)).join(', ')}。`);
  const qaScore = Math.max(0, 100 - issues.length * 25 - risk.length * 10);
  const passed = issues.length === 0 && fixed.srt.includes('-->') && fixed.voiceover_segments.length > 0;
  return { ...fixed, subtitle_qa: { passed, qa_score: qaScore, issues, corrections_made: corrections }, qa_passed: passed, qa_score: qaScore, qa_issues: issues, corrections_made: corrections, ready_for_agent6: passed };
}
const qaVoiceoverPackages = (data.draft_voiceover_packages || []).map((pkg) => { try { return qaPackage(pkg); } catch (error) { return { ...pkg, qa_passed: false, qa_score: 0, qa_issues: [`单条配音字幕 QA 失败：${error.message}`], corrections_made: [], ready_for_agent6: false }; } });
return [{ json: { ...data, status: 'qa_complete', qa_voiceover_packages: qaVoiceoverPackages } }];

const data = $input.first()?.json || {};
const generatedAt = new Date().toISOString();
const disclaimer = '本工具仅生成英文配音稿、字幕、SRT、配音节奏和 TTS Prompt，不实际生成音频，不调用 ElevenLabs 或任何外部 TTS 服务，也不构成医疗、法律或平台合规意见。最终制作和发布前仍需人工审核。';
function buildReport(status, packages, parseError) {
  const ready = packages.filter((pkg) => pkg.ready_for_agent6);
  const failed = packages.filter((pkg) => !pkg.ready_for_agent6);
  const lines = ['# AI Health OS — Agent 5 Voiceover & Subtitle Report', '', '## 一、本次处理结果', '', `- 状态：${status}`, `- 本次处理视觉方案数量：${packages.length}`, `- 可进入 Agent 6：${ready.length}`, `- 未通过 Subtitle QA：${failed.length}`];
  if (parseError) lines.push(`- 解析错误：${parseError}`);
  lines.push('', '## 二、可进入 Agent 6 的配音字幕包', '', ready.length ? ready.map((pkg) => `- ${pkg.video_title}｜QA ${pkg.qa_score} 分｜ready_for_agent6 = true`).join('\n') : '- 暂无。');
  lines.push('', '## 三、需要人工复核或未通过 QA 的内容', '', failed.length ? failed.map((pkg) => `- ${pkg.video_title}｜问题：${(pkg.qa_issues || []).join('；') || '未通过 QA'}`).join('\n') : '- 暂无。');
  lines.push('', '## 四、逐条配音与字幕', '');
  for (const pkg of packages) {
    lines.push(`### ${pkg.video_title}`, '', `- Voice Style：${pkg.voice_style}`, `- Estimated Duration：${pkg.estimated_duration_seconds} 秒`, `- QA：${pkg.qa_passed ? '通过' : '未通过'}（${pkg.qa_score} 分）`, `- TTS Prompt：${pkg.tts_prompt}`, '', '#### Full Voiceover', '', pkg.full_voiceover_script || '', '', '#### Segments', '', '| 分句 | 时间 | 配音文本 | 字幕 | 节奏 |', '| --- | --- | --- | --- | --- |');
    for (const segment of pkg.voiceover_segments || []) lines.push(`| ${segment.segment_number} | ${segment.start_time_seconds}s-${segment.end_time_seconds}s | ${segment.voiceover_text} | ${segment.subtitle_text} | ${segment.pacing} |`);
    lines.push('', '#### SRT', '', '```srt', pkg.srt || '', '```', '');
  }
  lines.push('## 五、下一步', '', '只有 `ready_for_agent6 = true` 的配音字幕包可以交给 Agent 6。当前不要开发 Agent 6，先人工检查语气、字幕可读性和健康表达安全性。', '', '## 重要说明', '', disclaimer);
  return lines.join('\n');
}
let status = 'success';
let packages = Array.isArray(data.qa_voiceover_packages) ? data.qa_voiceover_packages : [];
if (data.status === 'error') status = 'error';
if (data.status === 'insufficient_data') status = 'insufficient_data';
if (status !== 'success') packages = [];
const readyCount = packages.filter((pkg) => pkg.ready_for_agent6).length;
const failedCount = packages.filter((pkg) => !pkg.ready_for_agent6).length;
const manualReviewCount = packages.filter((pkg) => (pkg.corrections_made || []).length > 0 || (pkg.qa_issues || []).length > 0).length;
return [{ json: { workflow: 'AI Health OS', source_agent: 'agent_4', agent: 'agent_5', version: '1.1', status, generated_at: generatedAt, total_visual_plans: packages.length, voiceover_packages: packages, handoff: { next_agent: 'agent_6', ready_count: readyCount, failed_qa_count: failedCount, manual_review_count: manualReviewCount }, disclaimer, parse_error: data.parse_error || '', report_markdown: buildReport(status, packages, data.parse_error || '') } }];
